"""Compute proper strict factorizations from serial paths and two-hole exchange."""

from collections import Counter
from itertools import combinations

from relative_coherence_spherical_fibres import ring
from relative_coherence_strip_fibres import Complex


def strict_segments(model, paths):
    # Equality in the vertical category is generated by local two-hole exchanges.
    # Whiskering a segment exchange with its exterior extends it to a full path.
    parent = {h[a:b]: h[a:b] for h in paths for a, b in combinations(range(len(h) + 1), 2)}

    def root(segment):
        while segment != parent[segment]:
            parent[segment] = parent[parent[segment]]
            segment = parent[segment]
        return segment

    for dim, faces in zip(model.degrees, model.facets):
        if dim != 1:
            continue
        h, k = (model.cells[i] for i in faces)
        if h not in paths:
            continue
        changed = [i for i, (left, right) in enumerate(zip(h, k)) if left != right]
        i, j = changed
        assert j == i + 1
        for a in range(i + 1):
            for b in range(j + 1, len(h) + 1):
                parent[root(h[a:b])] = root(k[a:b])
    identifiers = {rep: i for i, rep in enumerate(sorted({root(s) for s in parent}))}
    return {s: identifiers[root(s)] for s in parent}


def cut_nerve(model, largest_cut=None):
    component, = model.components
    paths = {model.cells[i] for i in component if model.degrees[i] == 0}
    weight = len(next(iter(paths)))
    classes = strict_segments(model, paths)
    cut_limit = weight - 1 if largest_cut is None else min(largest_cut, weight - 1)
    levels = [{} for _ in range(cut_limit)]
    for h in paths:
        def simplex(cuts):
            ends = (0,) + cuts + (weight,)
            return tuple(classes[h[a:b]] for a, b in zip(ends, ends[1:]))

        for dim, row in enumerate(levels):
            for cuts in combinations(range(1, cut_limit + 1), dim + 1):
                label = simplex(cuts)
                faces = tuple(simplex(cuts[:i] + cuts[i + 1:]) for i in range(len(cuts))) if dim else ()
                assert row.setdefault(label, faces) == faces

    ranks = [0]
    for prior, row in zip(levels, levels[1:]):
        indices = {cell: i for i, cell in enumerate(prior)}
        pivots = {}
        for faces in row.values():
            column = 0
            for f in faces:
                column ^= 1 << indices[f]
            while column and column.bit_length() in pivots:
                column ^= pivots[column.bit_length()]
            if column:
                pivots[column.bit_length()] = column
        ranks.append(len(pivots))
    ranks.append(0)
    sizes = tuple(map(len, levels))
    betti = tuple(v - ranks[i] - ranks[i + 1] for i, v in enumerate(sizes))
    return sizes, betti, max(Counter(levels[1].values()).values())


if __name__ == '__main__':
    for n, expected in [(3, ((6, 6), (1, 1), 1)), (4, ((14, 36, 24), (1, 0, 1), 1))]:
        rules = {chr(65 + i): {i: ('a', 'b')} for i in range(n)}
        model = Complex(('a',) * n, ('b',) * n, rules)
        result = cut_nerve(model)
        assert result == expected and model.betti(model.components[0]) == (1,)
        print(f'{n} independent events: proper cut nerve {result}.')

    # A transient gate separates two positions of a probe between its birth and death.
    rules = {'A': {0: ('a', 'b'), 1: ('', 'd')},
             'B': {1: ('', ''), 2: ('p', 'q')},
             'C': {0: ('b', 'c'), 1: ('d', '')}}
    model = Complex(('a', '', 'p'), ('c', '', 'q'), rules)
    result = cut_nerve(model)
    print('Transient gate:', result, 'full Betti numbers', model.betti(model.components[0]))
    assert result[1:] == ((1, 1), 2) and model.betti(model.components[0]) == (1, 1)

    model = Complex(*ring(2))
    result = cut_nerve(model)
    print('Two-seam ring:', result)
    assert result[1] == (1, 1, 0, 0) and model.betti(model.components[0]) == (1, 1)
    truncated = cut_nerve(model, 3)
    print('Two-seam ring through the third cut:', truncated)
    assert truncated[1][:2] == (1, 1)

    # Distinguish the successive readings of the sole signal p by their temporal order.
    # Two readings cannot exchange, since both consume that gate. Forgetting the names
    # therefore identifies the chosen component with its uncoloured strict fibre.
    for m in range(1, 5):
        reads = 'BCDE'[:m]
        rules = {'A': {0: ('a', 'b'), 1: ('', 'd')}}
        rules.update({b: {1: ('', ''), 2: ('p', 'p')} for b in reads})
        model = Complex(('a', '', 'p'), ('b', 'd', 'p'), rules)
        for component in model.components:
            serial = [model.cells[i] for i in component if model.degrees[i] == 0]
            if ''.join(t[2] for t in serial[0] if t[2] != 'p') == reads:
                break
        else:
            raise AssertionError('missing temporal order')
        paths = {h for h in serial}
        classes = strict_segments(model, paths)
        first_a = {classes[h[1:]] for h in paths if h[0][0] == 'A'}
        assert len(set(classes[h[:1]] for h in paths if h[0][0] == 'A')) == 1
        assert len(first_a) == 2 ** m and model.betti(component) == (1,)
        assert len(serial) == 2 ** (m + 1) - 1
        print(f'{m} readings: {len(first_a)} distinct suffixes at the same first cut operation, '
              f'{len(serial)} serial vertices.')
